public enum AuthorizeError: Swift.Error {

    
    
    case AuthorizationFailed(errorMsg: String
    )
    case InvalidContext
    case InvalidInput(errorMsg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAuthorizeError: FfiConverterRustBuffer {
    typealias SwiftType = AuthorizeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AuthorizeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .AuthorizationFailed(
            errorMsg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidContext
        case 3: return .InvalidInput(
            errorMsg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AuthorizeError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .AuthorizationFailed(errorMsg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(errorMsg, into: &buf)
            
        
        case .InvalidContext:
            writeInt(&buf, Int32(2))
        
        
        case let .InvalidInput(errorMsg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(errorMsg, into: &buf)
            
        }
    }
}


