        switch variant {

        

        
        case 1: return .InvalidKey
        case 2: return .KeyNotFound(
            key: try FfiConverterString.read(from: &buf)
            )
        case 3: return .StorageLimitExceeded(
            max: try FfiConverterUInt64.read(from: &buf)
            )
        case 4: return .TtlExceeded(
            requested: try FfiConverterUInt64.read(from: &buf), 
            max: try FfiConverterUInt64.read(from: &buf)
            )
        case 5: return .ValueTooLarge(
            size: try FfiConverterUInt64.read(from: &buf), 
            max: try FfiConverterUInt64.read(from: &buf)
            )
        case 6: return .SerializationError(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
