        case let .KeyNotFound(key):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(key, into: &buf)
            
        
        case let .StorageLimitExceeded(max):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(max, into: &buf)
            
        
        case let .TtlExceeded(requested,max):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(requested, into: &buf)
            FfiConverterUInt64.write(max, into: &buf)
            
        
        case let .ValueTooLarge(size,max):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(size, into: &buf)
            FfiConverterUInt64.write(max, into: &buf)
            
        
        case let .SerializationError(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
